/* ---------- ті самі правила вибору завдання, що й у застосунку ---------- */
function pad(n) { return (n < 10 ? "0" : "") + n; }
function dkey(d) { d = d || new Date(); return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()); }
function dayNum(k) { const p = k.split("-"); return Math.round((Date.UTC(+p[0], +p[1] - 1, +p[2]) - Date.UTC(2024, 0, 1)) / 864e5); }
function hash32(str) { let h = 2166136261; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
function rng(seed) { let a = seed; return function () { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
function perm(seed, n) { const r = rng(hash32(seed)), a = []; for (let i = 0; i < n; i++) a.push(i); for (let j = n - 1; j > 0; j--) { const k = Math.floor(r() * (j + 1)); const t = a[j]; a[j] = a[k]; a[k] = t; } return a; }
function plural(n, one, few, many) { const m10 = n % 10, m100 = n % 100; if (m10 === 1 && m100 !== 11) return one; if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return few; return many; }
function ago(t) { const s = (Date.now() - t) / 1000; if (s < 60) return "щойно"; if (s < 3600) return Math.floor(s / 60) + " хв тому"; if (s < 86400) return Math.floor(s / 3600) + " год тому"; return Math.floor(s / 86400) + " дн. тому"; }

function parseCode(s) {
  s = (s || "").trim().replace(/\s+/g, "");
  let role = "A"; const bar = s.lastIndexOf("|");
  if (bar > 0) { role = s.slice(bar + 1).toUpperCase() === "B" ? "B" : "A"; s = s.slice(0, bar); }
  let m;
  if ((m = s.match(/^MNF-([a-z0-9]+)@(.+)$/i))) return { kind: "fb", id: m[1], url: "https://" + m[2].replace(/^https?:\/\//, "").replace(/\/+$/, ""), role };
  if ((m = s.match(/^MN-([A-Za-z0-9-]+)$/))) return { kind: "jb", id: m[1], role };
  return null;
}
async function loadDoc(p) {
  const fm = FileManager.local();
  const cache = fm.joinPath(fm.cacheDirectory(), "mizh-namy-" + p.id + ".json");
  const url = p.kind === "fb" ? p.url + "/mizhnamy/" + p.id + ".json" : "https://jsonblob.com/api/jsonBlob/" + p.id;
  try {
    const req = new Request(url); req.timeoutInterval = 12; req.headers = { Accept: "application/json" };
    const j = await req.loadJSON();
    if (j && j.users) { fm.writeString(cache, JSON.stringify(j)); return j; }
  } catch (e) {}
  if (fm.fileExists(cache)) return JSON.parse(fm.readString(cache));
  return null;
}

const MOODS = ["😔", "😐", "🙂", "😊", "🥰"];
const ROSE = new Color("#D63F6A"), ROSE2 = new Color("#F4809A"), WHITE = Color.white();

async function build() {
  const w = new ListWidget();
  const g = new LinearGradient(); g.colors = [ROSE, ROSE2]; g.locations = [0, 1]; g.startPoint = new Point(0, 0); g.endPoint = new Point(1, 1);
  w.backgroundGradient = g;
  w.setPadding(14, 16, 14, 16);
  w.refreshAfterDate = new Date(Date.now() + 15 * 60 * 1000);
  if (APP_URL.indexOf("YOUR-SITE") < 0) w.url = APP_URL;
  const fam = config.widgetFamily || "medium";

  const p = parseCode(CODE || args.widgetParameter || "");
  if (!p) {
    const t = w.addText("💞 Між нами"); t.font = Font.boldSystemFont(15); t.textColor = WHITE;
    w.addSpacer(6);
    const s = w.addText("Утримуй віджет → Редагувати → встав код для віджета з налаштувань застосунку в Parameter.");
    s.font = Font.systemFont(11); s.textColor = WHITE; s.textOpacity = .9;
    return w;
  }
  const doc = await loadDoc(p);
  const me = p.role, them = me === "A" ? "B" : "A";
  const k = dkey();
  const users = (doc && doc.users) || {};
  const U = users[me] || {}, T = users[them] || {};
  const days = (doc && doc.days) || {};
  const dm = (days[k] && days[k][me]) || {}, dt = (days[k] && days[k][them]) || {};
  const rer = ((days[k] && days[k].A && days[k].A.reroll) || 0) + ((days[k] && days[k].B && days[k].B.reroll) || 0);
  const n = DATA.tasks.length, pr = perm(p.id + ":t", n);
  const task = DATA.tasks[pr[((dayNum(k) + rer * 53) % n + n) % n]];
  const cat = DATA.cats[task.c];

  // серія днів поспіль
  function both(key) { const d = days[key]; return d && d.A && d.A.done && d.B && d.B.done; }
  let s = 0; let dd = new Date(); if (!both(dkey(dd))) dd.setDate(dd.getDate() - 1);
  while (both(dkey(dd)) && s < 3000) { s++; dd.setDate(dd.getDate() - 1); }

  // шапка
  const top = w.addStack(); top.centerAlignContent();
  const brand = top.addText("💞 Між нами"); brand.font = Font.boldSystemFont(fam === "small" ? 12 : 13); brand.textColor = WHITE;
  top.addSpacer();
  if (doc && doc.meta && doc.meta.startDate && fam !== "small") {
    const sp = doc.meta.startDate.split("-"); const st = new Date(+sp[0], +sp[1] - 1, +sp[2]);
    const t0 = new Date(); t0.setHours(0, 0, 0, 0);
    const nd = Math.max(0, Math.round((t0 - st) / 864e5));
    const tg = top.addText("разом " + nd + " " + plural(nd, "день", "дні", "днів")); tg.font = Font.mediumSystemFont(11); tg.textColor = WHITE; tg.textOpacity = .85;
  } else if (s > 0) { const f = top.addText("🔥" + s); f.font = Font.boldSystemFont(12); f.textColor = WHITE; }

  w.addSpacer(fam === "small" ? 6 : 8);
  const label = w.addText(cat.e + " Завдання дня"); label.font = Font.semiboldSystemFont(10); label.textColor = WHITE; label.textOpacity = .8;
  w.addSpacer(3);
  const tt = w.addText(task.t);
  tt.font = new Font("NewYork-Semibold", fam === "small" ? 13 : (fam === "large" ? 19 : 15));
  tt.textColor = WHITE; tt.minimumScaleFactor = .7;
  tt.lineLimit = fam === "small" ? 4 : (fam === "large" ? 6 : 3);
  w.addSpacer();

  // пінг від коханої людини
  if (T.pingAt && Date.now() - T.pingAt < 24 * 3600 * 1000 && fam !== "small") {
    const pg = w.addText("💗 " + (T.name || "Кохана людина") + " думає про тебе · " + ago(T.pingAt));
    pg.font = Font.semiboldSystemFont(11); pg.textColor = WHITE; pg.lineLimit = 1;
    w.addSpacer(4);
  }

  const row = w.addStack(); row.centerAlignContent(); row.spacing = 8;
  const a = row.addText((dm.done ? "✓ " : "○ ") + (fam === "small" ? "Я" : (U.name || "Я"))); a.font = Font.semiboldSystemFont(11); a.textColor = WHITE; a.textOpacity = dm.done ? 1 : .75;
  const b = row.addText((dt.done ? "✓ " : "○ ") + (fam === "small" ? (T.name || "").slice(0, 8) || "Ти" : (T.name || "Кохана людина"))); b.font = Font.semiboldSystemFont(11); b.textColor = WHITE; b.textOpacity = dt.done ? 1 : .75;
  if (fam !== "small") {
    row.addSpacer();
    if (T.moodDay === k && T.mood != null) { const md = row.addText(MOODS[T.mood]); md.font = Font.systemFont(14); }
    if (s > 0) { const f = row.addText("🔥" + s); f.font = Font.boldSystemFont(12); f.textColor = WHITE; }
  }
  if (fam === "large") {
    w.addSpacer(10);
    const qn = DATA.questions.length, qp = perm(p.id + ":q", qn);
    const ql = w.addText("❓ Питання дня"); ql.font = Font.semiboldSystemFont(10); ql.textColor = WHITE; ql.textOpacity = .8;
    const q = w.addText(DATA.questions[qp[(dayNum(k) % qn + qn) % qn]]); q.font = new Font("NewYork-Regular", 14); q.textColor = WHITE;
    const st = w.addText((dm.answer ? "✓ ти відповів(ла)" : "○ ти ще не відповів(ла)") + " · " + (dt.answer ? "✓ " : "○ ") + (T.name || "")); st.font = Font.systemFont(10); st.textColor = WHITE; st.textOpacity = .8;
  }
  return w;
}

const widget = await build();
if (config.runsInWidget) Script.setWidget(widget);
else await widget.presentMedium();
Script.complete();
